import "core-js/modules/es6.function.name";
export default {
  props: {
    chartData: {
      type: Array
    }
  },
  data: function data() {
    return {
      total: 0
    };
  },
  watch: {
    chartData: function chartData() {
      // this.total = this.chartData[0].value + this.chartData[1].value
      if (this.chartData.length == 1) {
        if (this.chartData[0].name == '在线') {
          this.chartData.unshift({
            name: '离线',
            value: 0
          });
        } else if (this.chartData[0].name == '离线') {
          this.chartData.push({
            name: '在线',
            value: 0
          });
        }
      }
      this.initChart();
    }
  },
  mounted: function mounted() {},
  methods: {
    initChart: function initChart() {
      var _this = this;
      var diskChart = this.$echarts.init(document.getElementById('diskChart'));
      diskChart.setOption({
        tooltip: {
          trigger: 'item'
        },
        legend: {
          // top:'center',
          // orient: 'vertical',
          // right: 20,
          formatter: function formatter(val) {
            var text;
            for (var i = 0; i < _this.chartData.length; i++) {
              var item = _this.chartData[i];
              if (val == item.name) text = val + item.value;
            }
            return text;
          }
        },
        color: ["#2293FF", '#f18940'],
        series: [{
          type: 'pie',
          data: [this.chartData[1], this.chartData[0]],
          radius: ['55%', '75%'],
          center: ['50%', '55%'],
          label: {
            show: true,
            // position: 'center',
            formatter: function formatter(val) {
              return val.name + '(' + val.percent.toFixed(1) + '%)';
            }
          },
          emphasis: {
            itemStyle: {
              shadowBlur: 10,
              shadowOffsetX: 0,
              shadowColor: 'rgba(0,0,0,0.5)'
            }
          },
          labelLine: {
            show: true
          }
        }]
      });
      diskChart.on('click', function (param) {
        _this.$router.push({
          path: '/control/monitor/online'
        });
      });
    }
  }
};
